sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        g_form.hideFieldMsg('valid_to', true);
        return;
    }

    var validFrom = g_form.getValue('valid_from');
    var validTo = newValue;
    g_form.hideFieldMsg('valid_to', true);

    if (validFrom && validTo) {
        if (validTo <= validFrom) {
            g_form.showFieldMsg('valid_to', 'Valid To date must be greater than Valid From date (' + validFrom + ').', 'error');
        }
    }
}
